1	package cli
2	
3	import (
4		"context"
5		"crypto/rand"
6		"encoding/hex"
7		"errors"
8		"fmt"
9		"os"
10		"path/filepath"
11		"runtime"
12		"strings"
13		"time"
14	
15		"golang.org/x/mod/semver"
16	)
17	
18	// Remote install orchestration: resolve tag → fetch metadata → download +
19	// verify + extract → place under pkg/<name>/ → link into bin/ → write
20	// manifest. The bin/ link goes through the same InstallPluginFromPath used
21	// by local-dev installs, so conflict handling, atomic replace, and the
22	// Windows symlink fallbacks are shared, not duplicated.
23	
24	// maxTagFallbacks bounds how many tags we walk down when the newest tag has
25	// no published assets (tag pushed, release not finished).
26	const maxTagFallbacks = 3
27	
28	// RemoteInstallOptions configures InstallPluginFromRepo. It holds only genuine
29	// options — the repository and the expected name are required arguments,
30	// because a caller that omits either is making a decision, not accepting a
31	// default.
32	type RemoteInstallOptions struct {
33		// Pin, when non-empty, installs exactly this tag and marks the
34		// manifest pinned so upgrade skips it.
35		Pin string
36		// Force replaces an existing managed entry with the same name.
37		Force bool
38		// AllowUnverified permits installing a release that publishes no
39		// checksums.txt covering this platform. Off by default: downloading and
40		// executing an unauthenticated binary is the supply-chain risk the
41		// checksum path exists to remove, so it takes an explicit opt-in.
42		AllowUnverified bool
43	}
44	
45	// RemoteInstallResult is what a successful remote install produced.
46	type RemoteInstallResult struct {
47		Installed *InstalledPlugin
48		Manifest  *PluginManifest
49		Metadata  *PluginMetadata
50		// SkippedTags lists newer tags that were passed over for missing
51		// assets, newest first. Callers surface these as warnings.
52		SkippedTags []string
53	}
54	
55	// InstallPluginFromRepo installs a plugin from a git repository URL.
56	// Dependency resolution deliberately does not happen here — callers
57	// (the install command) plan and confirm dependency installs first.
58	// expectedName is the plugin name the caller has already committed to — the
59	// index entry the user asked for, the requirement being satisfied, or the
60	// plugin being upgraded. Pass "" only for a bare `install <url>`, where the
61	// repository legitimately names itself; installRepoAtTag explains why a
62	// mismatch is otherwise fatal.
63	//
64	// It is a required argument rather than an options field on purpose. As a
65	// field it could be silently omitted, and omitting it reopens a no-prompt
66	// name-substitution hole; as an argument, passing "" is a visible choice at
67	// the call site.
68	func InstallPluginFromRepo(ctx context.Context, repoURL, expectedName string, opts RemoteInstallOptions) (*RemoteInstallResult, error) {
69		repoURL = strings.TrimRight(repoURL, "/")
70	
71		var tags []string
72		if opts.Pin != "" {
73			tags = []string{opts.Pin}
74		} else {
75			var err error
76			tags, err = listRemoteSemverTags(ctx, repoURL)
77			if err != nil {
78				return nil, err
79			}
80			if len(tags) == 0 {
81				return nil, fmt.Errorf("%s has no stable semver tags; prereleases are skipped, so pass --pin <tag> to install one (or a non-semver tag)", redactURL(repoURL))
82			}
83			if len(tags) > maxTagFallbacks {
84				tags = tags[:maxTagFallbacks]
85			}
86		}
87	
88		var lastErr error
89		for i, tag := range tags {
90			res, err := installRepoAtTag(ctx, repoURL, expectedName, tag, opts)
91			if err == nil {
92				res.SkippedTags = tags[:i]
93				return res, nil
94			}
95			lastErr = err
96			if !errors.Is(err, errAssetNotFound) {
97				return nil, err
98			}
99		}
100		return nil, lastErr
101	}
102	
103	func installRepoAtTag(ctx context.Context, repoURL, expectedName, tag string, opts RemoteInstallOptions) (*RemoteInstallResult, error) {
104		meta, err := fetchPluginMetadataAtTag(ctx, repoURL, tag)
105		if err != nil {
106			return nil, err
107		}
108		// The installed name comes from the *remote* — entire-plugin.yml's name:,
109		// else the repo basename.
110		var name string
111		if meta != nil && meta.Name != "" {
112			name = meta.Name
113		} else if name, err = pluginNameFromRepoURL(repoURL); err != nil {
114			return nil, err
115		}
116	
117		// Reconcile it with what the caller asked for. Unchecked, the remote chose
118		// the name unilaterally, which broke three things:
119		//
120		//  - `install <index-name>` could install something else entirely: the
121		//    index entry says "safe", the repo declares "hijack", and the user gets
122		//    entire-hijack on PATH with no prompt (index installs never prompt).
123		//  - --force escalated across plugins: the already-installed check below
124		//    tests the *remote-declared* name, so reinstalling A let A's repo
125		//    declare name: B and replace an unrelated installed B.
126		//  - A dependency installed under a different name never satisfied the
127		//    requirement, so dependencySatisfied/doctor reported it missing forever
128		//    and every future parent install re-attempted it.
129		//
130		// Fatal rather than a warning: every caller that sets ExpectedName has
131		// already made a trust decision about *that* name, and silently honoring a
132		// different one voids it. A legitimate rename is a catalog or requirement
133		// to fix, and the message says so.
134		if expectedName != "" && name != expectedName {
135			return nil, fmt.Errorf(
136				"%s declares plugin name %q but %q was requested; refusing to install under a name that was not asked for (update the plugin index entry or the requirement if the plugin was renamed)",
137				redactURL(repoURL), name, expectedName)
138		}
139	
140		if existing, err := FindInstalledPlugin(name); err != nil {
141			return nil, err
142		} else if existing != nil && !opts.Force {
143			return nil, fmt.Errorf("plugin %q already installed at %s; use --force to replace", name, existing.Path)
144		}
145	
146		staging, err := os.MkdirTemp("", "entire-plugin-fetch-")
147		if err != nil {
148			return nil, fmt.Errorf("create staging dir: %w", err)
149		}
150		defer os.RemoveAll(staging)
151	
152		asset, err := downloadPluginAsset(ctx, meta, repoURL, name, tag, staging, opts.AllowUnverified)
153		if err != nil {
154			return nil, err
155		}
156	
157		binBase := pluginBinaryName(name)
158		stagedBin := filepath.Join(staging, "extracted-"+binBase)
159		if err := extractPluginBinary(asset.Path, name, stagedBin); err != nil {
160			return nil, err
161		}
162	
163		pkgDir, err := EnsurePluginPkgDir(name)
164		if err != nil {
165			return nil, err
166		}
167		sweepOldBinaries(pkgDir)
168		pkgBin := filepath.Join(pkgDir, binBase)
169		if err := replaceBinary(stagedBin, pkgBin); err != nil {
170			return nil, fmt.Errorf("place plugin binary: %w", err)
171		}
172	
173		// Digest the binary we actually placed, not just the archive it came from.
174		// asset.SHA256 covers the downloaded asset, which is discarded with the
175		// staging dir — so it records provenance but can never detect later
176		// tampering. binDigest is what `plugin doctor` re-checks.
177		binDigest, err := fileSHA256(pkgBin)
178		if err != nil {
179			return nil, fmt.Errorf("hash installed plugin binary: %w", err)
180		}
181	
182		installed, err := InstallPluginFromPath(InstallPluginOptions{SourcePath: pkgBin, Force: true})
183		if err != nil {
184			return nil, err
185		}
186	
187		manifest := &PluginManifest{
188			Name:         name,
189			RepoURL:      repoURL,
190			Tag:          tag,
191			Asset:        asset.Asset,
192			SHA256:       asset.SHA256,
193			BinarySHA256: binDigest,
194			Unverified:   !asset.Verified,
195			Pinned:       opts.Pin != "",
196			InstalledAt:  time.Now().UTC(),
197		}
198		if meta != nil {
199			manifest.Requires = meta.Requires
200		}
201		if err := SavePluginManifest(manifest); err != nil {
202			return nil, err
203		}
204		return &RemoteInstallResult{Installed: installed, Manifest: manifest, Metadata: meta}, nil
205	}
206	
207	// UpgradeOutcome describes what UpgradeInstalledPlugin did.
208	type UpgradeOutcome struct {
209		Name string
210		// Pinned: skipped because the manifest is pinned.
211		Pinned bool
212		// UpToDate: already at the newest tag.
213		UpToDate bool
214		// FromTag/ToTag are set when an upgrade actually happened.
215		FromTag, ToTag string
216	}
217	
218	// UpgradeInstalledPlugin re-resolves the newest tag for a remote-installed
219	// plugin and reinstalls when it differs from the manifest's tag. Plugins
220	// without a manifest (local-dev symlinks) are not upgradable.
221	func UpgradeInstalledPlugin(ctx context.Context, name string) (*UpgradeOutcome, error) {
222		m, err := LoadPluginManifest(name)
223		if err != nil {
224			return nil, err
225		}
226		if m == nil {
227			return nil, fmt.Errorf("plugin %q has no install manifest (local-dev install?); reinstall it from its repository URL to make it upgradable", name)
228		}
229		if m.Pinned {
230			return &UpgradeOutcome{Name: name, Pinned: true}, nil
231		}
232		tags, err := listRemoteSemverTags(ctx, m.RepoURL)
233		if err != nil {
234			return nil, err
235		}
236		if len(tags) == 0 {
237			return nil, fmt.Errorf("%s has no stable semver tags; prereleases are skipped, so pass --pin <tag> to move to one", redactURL(m.RepoURL))
238		}
239		// Semver comparison, not string equality: "v0.2.0" and "0.2.0" are the
240		// same version, and a remote that re-tagged with the other spelling
241		// must not trigger a reinstall.
242		if semver.Compare(canonicalSemver(tags[0]), canonicalSemver(m.Tag)) <= 0 {
243			return &UpgradeOutcome{Name: name, UpToDate: true}, nil
244		}
245		// Inherit the install-time trust decision: a plugin the user knowingly
246		// installed unverified shouldn't start failing on upgrade, and one
247		// installed verified must not silently downgrade to unverified.
248		res, err := InstallPluginFromRepo(ctx, m.RepoURL, name, RemoteInstallOptions{
249			Force: true, AllowUnverified: m.Unverified,
250		})
251		if err != nil {
252			return nil, err
253		}
254		// The install may have fallen back past an asset-less newest tag and
255		// landed on the version already installed — that's up-to-date, not an
256		// upgrade line claiming X → X.
257		if semver.Compare(canonicalSemver(res.Manifest.Tag), canonicalSemver(m.Tag)) <= 0 {
258			return &UpgradeOutcome{Name: name, UpToDate: true}, nil
259		}
260		return &UpgradeOutcome{Name: name, FromTag: m.Tag, ToTag: res.Manifest.Tag}, nil
261	}
262	
263	// replaceBinary moves src over dest atomically. On Windows, a running
264	// executable can't be replaced (sharing violation) but it *can* be renamed:
265	// move the old binary aside to a .old-<rand> file and retry; leftovers are
266	// swept on the next install. os.Rename fails across filesystems (staging is
267	// in the system temp dir), so a copy fallback covers that case.
268	func replaceBinary(src, dest string) error {
269		err := os.Rename(src, dest)
270		if err == nil {
271			return nil
272		}
273		if runtime.GOOS == windowsGOOS {
274			if asideErr := os.Rename(dest, oldBinaryAsidePath(dest)); asideErr == nil {
275				if err = os.Rename(src, dest); err == nil {
276					return nil
277				}
278			}
279		}
280		// Cross-device rename: copy + fsync-free write, then remove src.
281		in, openErr := os.Open(src) //nolint:gosec // staging file we created
282		if openErr != nil {
283			return errors.Join(err, openErr)
284		}
285		defer in.Close()
286		if writeErr := writeExecutable(in, dest); writeErr != nil {
287			return errors.Join(err, writeErr)
288		}
289		_ = os.Remove(src)
290		return nil
291	}
292	
293	// oldBinaryAsidePath returns a unique .old- sibling path for the
294	// rename-aside trick. Random suffix so concurrent upgrades can't collide.
295	func oldBinaryAsidePath(dest string) string {
296		var b [4]byte
297		if _, err := rand.Read(b[:]); err != nil {
298			return dest + ".old-fallback"
299		}
300		return dest + ".old-" + hex.EncodeToString(b[:])
301	}
302	
303	// sweepOldBinaries best-effort removes .old-* leftovers from the Windows
304	// rename-aside fallback. Failures are ignored — the files are inert.
305	func sweepOldBinaries(pkgDir string) {
306		entries, err := os.ReadDir(pkgDir)
307		if err != nil {
308			return
309		}
310		for _, e := range entries {
